# Cessation fact sheets (19 Nov 2026, owner's request): alcohol, cannabis, gambling, social media. Smoking already at /quit-smoking/.
ADF_HL = "National Alcohol and Other Drug Hotline: 1800 250 015 (free, 24/7)"

fact("alcohol",
 "Cutting Down or Quitting Alcohol: Limits, Withdrawal and Medicines",
 "How to cut down or stop drinking: the Australian limit of 10 standard drinks a week, signs alcohol is a problem, safe withdrawal, medicines that help (naltrexone, acamprosate) and where to get support.",
 "Cutting down or quitting alcohol", "cutting down alcohol",
 "Australian guidelines say healthy adults should drink no more than 10 standard drinks a week and no more than 4 on any one day. Less is lower risk. If you drink heavily every day, don’t stop suddenly without medical advice: withdrawal can be dangerous.",
 h2("The guidelines", [
   "Healthy adults: <b>no more than 10 standard drinks a week</b> and <b>no more than 4 on any one day</b>.",
   "Under 18s: no alcohol. Pregnant, planning pregnancy or breastfeeding: no alcohol is safest.",
   "A standard drink is 10 g of alcohol: roughly a middy of full-strength beer, a 100 mL glass of wine or a 30 mL nip of spirits.",
   "Alcohol causes at least 7 cancers (including breast and bowel), liver disease, high blood pressure, atrial fibrillation and injuries."]) +
 h2("Signs it’s becoming a problem", [
   "Drinking more or longer than you meant to; trying and failing to cut down.",
   "Cravings, needing more for the same effect, or drinking to stop shakes or anxiety in the morning.",
   "Missing work or family commitments, or arguments about drinking.",
   "Drinking in risky situations, like before driving."]) +
 h2("Cutting down: what works", [
   "Count your drinks: use an app or a note on your phone.",
   "Have alcohol-free days each week, and start later in the day.",
   "Alternate with water; choose low-alcohol options; use smaller glasses.",
   "Plan for triggers (stress, certain people, after work) and have something else ready.",
   "Tell people you’re cutting down. Support doubles your chances."]) +
 h2("Stopping safely", [
   "If you drink heavily every day, stopping suddenly can cause <b>shakes, sweating, anxiety, seizures or delirium tremens</b>, which can be life-threatening.",
   "See your GP first: supervised withdrawal at home or in a detox unit, often with diazepam for a few days, and thiamine (vitamin B1) to protect the brain.",
   "Withdrawal usually starts 6 to 24 hours after the last drink and peaks at 1 to 3 days."]) +
 h2("Medicines that help", [
   "<b>Naltrexone</b>: reduces cravings and heavy drinking days. See the <a href=\"/medicines/naltrexone/\">naltrexone guide</a>.",
   "<b>Acamprosate</b>: helps people stay alcohol-free after stopping; safe with liver disease.",
   "<b>Disulfiram</b>: makes you sick if you drink; only for some people, with supervision.",
   "These work best alongside counselling, support groups or a GP plan."]) +
 h2("Where to get help", [ADF_HL, "Counselling Online: free 24/7 web chat about alcohol and drugs (counsellingonline.org.au)", "Your GP: a check-up, blood tests and a plan", "Support groups such as SMART Recovery and Alcoholics Anonymous"]),
 [("How many drinks a week is safe in Australia?", "The guideline is no more than 10 standard drinks a week and no more than 4 on any one day for healthy adults. Fewer is lower risk."),
  ("Is it dangerous to stop drinking suddenly?", "If you drink heavily every day, yes. Withdrawal can cause seizures and delirium tremens. See a doctor for a supervised plan."),
  ("What medicines help you stop drinking?", "Naltrexone and acamprosate both reduce relapse. Disulfiram is used for some people. Your GP can prescribe them."),
  ("How long does alcohol withdrawal last?", "It usually starts 6 to 24 hours after the last drink, peaks at 1 to 3 days and settles within about a week.")],
 [("Alcohol and Drug Foundation", "https://adf.org.au/", "Facts, support services and the national hotline.")],
 [("NHMRC: Australian guidelines to reduce health risks from drinking alcohol", "https://www.nhmrc.gov.au/health-advice/alcohol"), ("Alcohol and Drug Foundation", "https://adf.org.au/")],
 [("Naltrexone", "/medicines/naltrexone/"), ("Quit smoking", "/quit-smoking/"), ("Quitting cannabis", "/cannabis/")],
 groups=["Heart and lifestyle"], blurb="The 10-drinks-a-week guideline, safe withdrawal and medicines that help.",
 search="alcohol cutting down quit drinking standard drinks guidelines withdrawal detox naltrexone acamprosate disulfiram binge drinking")

fact("cannabis",
 "Cannabis (Marijuana): Effects, Dependence and How to Quit",
 "Cannabis explained: dependence, withdrawal (irritability, sleep problems, cravings), psychosis risk, cannabinoid hyperemesis syndrome, driving laws, medicinal cannabis, and how to cut down or quit.",
 "Cannabis: effects and quitting", "cannabis",
 "Cannabis (marijuana, weed) is the most widely used illicit drug in Australia. Most people who use it don’t become dependent, but regular use, especially of high-THC products or starting young, raises the risk of dependence, psychosis and other harms.",
 h2("Effects and risks", [
   "Short term: relaxation, altered perception, slower reactions, poor memory and coordination, anxiety or paranoia in some.",
   "<b>Dependence</b>: regular users can become dependent, needing it to get through the day.",
   "<b>Mental health</b>: THC raises the risk of psychosis and schizophrenia, more with frequent, high-potency use and starting in the teens.",
   "<b>Cannabinoid hyperemesis syndrome</b>: repeated bouts of vomiting and tummy pain in heavy long-term users, often eased by hot showers; the only cure is stopping.",
   "Smoking it harms the lungs; use in pregnancy is linked to lower birth weight."]) +
 h2("Withdrawal", [
   "Starts within 1 to 2 days of stopping and is mostly gone within about 3 weeks.",
   "Irritability, anxiety, low mood, trouble sleeping, vivid dreams, reduced appetite, restlessness and cravings.",
   "Usually mild and not dangerous, but enough to make quitting hard."]) +
 h2("How to cut down or quit", [
   "Pick a quit date or a cutting-down plan (fewer days, smaller amounts, lower THC).",
   "Remove supplies and equipment; change routines linked to using.",
   "Plan for sleep problems: regular wake time, exercise, less caffeine.",
   "Counselling (CBT, motivational interviewing) is the most effective treatment; there’s no approved medicine for cannabis dependence.",
   "Your GP can help with sleep and mood during withdrawal."]) +
 h2("Driving and the law", [
   "Don’t drive after using cannabis. Roadside drug tests detect THC, and in most states it’s an offence to drive with any THC present, even if prescribed.",
   "Medicinal cannabis is legal only on prescription through TGA pathways."]) +
 h2("Where to get help", [ADF_HL, "Counselling Online: free 24/7 web chat (counsellingonline.org.au)", "Your GP or a local alcohol and drug service"]),
 [("Is cannabis addictive?", "It can be. Regular use can lead to dependence, with cravings and withdrawal when stopping. The risk is higher with daily use, high-THC products and starting young."),
  ("How long does cannabis withdrawal last?", "Symptoms start within 1 to 2 days, peak in the first week and are mostly gone within about 3 weeks."),
  ("What is cannabinoid hyperemesis syndrome?", "Recurring severe vomiting and tummy pain in long-term heavy users. Hot showers ease it temporarily; stopping cannabis cures it."),
  ("Can I drive on medicinal cannabis?", "In most Australian states it’s an offence to drive with THC in your system, even with a prescription. Check your state’s rules.")],
 [("Alcohol and Drug Foundation: Cannabis", "https://adf.org.au/drug-facts/cannabis/", "Effects, harms and support.")],
 [("Alcohol and Drug Foundation: Cannabis", "https://adf.org.au/drug-facts/cannabis/")],
 [("Cutting down alcohol", "/alcohol/"), ("Quit smoking", "/quit-smoking/"), ("Anxiety", "/anxiety/")],
 groups=["Other"], blurb="Dependence, withdrawal, psychosis risk and how to quit.",
 search="cannabis marijuana weed quit cannabis withdrawal dependence cannabinoid hyperemesis syndrome psychosis THC CBD medicinal cannabis driving")

fact("gambling",
 "Gambling Problems: Signs, BetStop, Blocking Tools and Help",
 "Gambling harm explained: warning signs, how to stop or cut down, BetStop self-exclusion, bank gambling blocks, treatment that works, and free 24/7 support across Australia.",
 "Gambling problems", "gambling problems",
 "Gambling harm is common and treatable. Free counselling is available 24/7, and tools like BetStop and bank gambling blocks make it much harder to bet on impulse.",
 h2("Warning signs", [
   "Betting more than you can afford, or chasing losses.",
   "Needing to bet more to get the same buzz; feeling restless when trying to stop.",
   "Hiding gambling, borrowing money or selling things to gamble.",
   "Gambling affecting your relationships, work, mood or sleep.",
   "Gambling disorder is a recognised mental health condition."]) +
 h2("Blocking tools", [
   "<b>BetStop</b>: the free national self-exclusion register that blocks you from all licensed Australian online and phone betting providers (betstop.gov.au).",
   "<b>Bank gambling blocks</b>: most major banks let you block gambling transactions in their app.",
   "Venue self-exclusion for pubs, clubs and casinos.",
   "Blocking software on phones and computers; delete betting apps."]) +
 h2("What helps", [
   "Cognitive behavioural therapy (CBT) has the best evidence.",
   "Financial counselling to deal with debt (free through the National Debt Helpline: 1800 007 007).",
   "Hand over control of money for a while to someone you trust.",
   "Naltrexone has some evidence for reducing gambling urges; ask your GP.",
   "Treat what comes with it: depression, anxiety, alcohol use."]) +
 h2("Where to get help", ["Gambling Help: 1800 858 858 (free, 24/7)", "Gambling Help Online: 24/7 chat and email (gamblinghelponline.org.au)", "Lifeline 13 11 14 if you’re in crisis"]),
 [("How do I ban myself from betting apps in Australia?", "Register with BetStop, the free national self-exclusion register. It blocks you from all licensed Australian online and phone gambling providers."),
  ("Can my bank block gambling?", "Yes. Most major Australian banks offer gambling transaction blocks in their app or on request."),
  ("Is there free help for gambling?", "Yes. Call Gambling Help on 1800 858 858 or use Gambling Help Online for 24/7 chat and counselling."),
  ("Is gambling addiction a mental illness?", "Gambling disorder is a recognised condition, and treatments like CBT work.")],
 [("BetStop: National Self-Exclusion Register", "https://www.betstop.gov.au/", "Block yourself from online and phone betting."), ("Gambling Help Online", "https://www.gamblinghelponline.org.au/", "24/7 chat, email and self-help.")],
 [("BetStop", "https://www.betstop.gov.au/"), ("Gambling Help Online", "https://www.gamblinghelponline.org.au/"), ("Department of Social Services: Gambling support services", "https://www.dss.gov.au/gambling/gambling-support-services")],
 [("Depression", "/depression/"), ("Anxiety", "/anxiety/"), ("Naltrexone", "/medicines/naltrexone/")],
 groups=["Other"], blurb="Warning signs, BetStop and bank blocks, and free 24/7 help.",
 search="gambling problem gambling addiction pokies betting apps BetStop self-exclusion bank gambling block gambling help 1800 858 858")

fact("social-media",
 "Cutting Back on Social Media: Sleep, Mood and Practical Tips",
 "Problematic social media use explained: what the evidence says about mood and sleep, Australia's under-16 social media minimum age, and practical ways to cut back for adults and families.",
 "Cutting back on social media", "social media use",
 "Social media isn’t a diagnosis, but heavy or compulsive use can crowd out sleep, exercise and time with people. The research on mood is mixed: effects on average are small, but some people, especially teens, are affected much more.",
 h2("What the evidence says", [
   "Average links between social media time and depression or anxiety are small, and cause and effect is hard to untangle.",
   "Some uses seem worse than others: late-night scrolling, comparison, cyberbullying and content about self-harm or eating.",
   "Sleep is the clearest casualty: phones in bed delay and disturb sleep.",
   "Many people feel better after cutting back, in small trials."]) +
 h2("Signs it’s a problem", [
   "Checking compulsively, or losing hours without meaning to.",
   "Feeling worse about yourself or anxious after using it.",
   "It’s getting in the way of sleep, study, work or relationships.",
   "Feeling irritable or anxious when you can’t check."]) +
 h2("Practical ways to cut back", [
   "Turn off non-essential notifications.",
   "Set app limits; move apps off your home screen; log out after use.",
   "Keep phones out of the bedroom; charge them elsewhere.",
   "Try greyscale mode, which makes feeds less appealing.",
   "Unfollow accounts that make you feel worse.",
   "Replace the habit: a book, a walk, a call to a friend."]) +
 h2("Children and teens", [
   "Since 10 December 2025, Australian law requires major social media platforms to take reasonable steps to stop under-16s having accounts.",
   "Family media plans, devices out of bedrooms at night and modelling good habits help.",
   "The eSafety Commissioner has guides for parents and reporting tools for cyberbullying (esafety.gov.au)."]) +
 h2("Where to get help", ["Your GP, if mood, anxiety or sleep are suffering", "Kids Helpline: 1800 55 1800 (5 to 25 year olds)", "Lifeline 13 11 14 if you’re in crisis"]),
 [("Is social media bad for mental health?", "On average the link is small, but some people, especially teens and those who use it late at night or compare themselves a lot, are affected more. Sleep is the clearest harm."),
  ("What is Australia’s social media age limit?", "From 10 December 2025, major social media platforms must take reasonable steps to stop under-16s having accounts."),
  ("How can I use social media less?", "Turn off notifications, set app limits, keep your phone out of the bedroom, try greyscale mode and unfollow accounts that make you feel worse.")],
 [("eSafety Commissioner: Social media age restrictions", "https://www.esafety.gov.au/social-media-age-restrictions", "What the under-16 law means for families.")],
 [("eSafety Commissioner: Social media age restrictions", "https://www.esafety.gov.au/social-media-age-restrictions")],
 [("Sleep", "/sleep/"), ("Anxiety", "/anxiety/"), ("Depression", "/depression/")],
 groups=["Other"], blurb="What the evidence says, the under-16 law and practical ways to cut back.",
 search="social media addiction screen time phone addiction doomscrolling teens under 16 social media ban sleep mental health cut back")
